def transform(grid):
    rows = len(grid)
    cols = len(grid[0])

    if rows < 3 or cols < 3:
        return [row[:] for row in grid]

    result = [row[:] for row in grid]

    for r in range(rows):
        for c in range(cols):
            color = grid[r][c]

            # Skip background (3 or 9)
            if color in (3, 9):
                continue

            # Try to find rectangle from this cell as top-left
            corners = [r, c]

            # Expand right
            c_end = c
            while c_end + 1 < cols and grid[r][c_end + 1] == color:
                c_end += 1

            if c_end == c:
                continue

            # Expand down
            r_end = r
            while r_end + 1 < rows and grid[r_end + 1][c] == color:
                r_end += 1

            if r_end == r:
                continue

            # Must have interior (needs at least 3x3 for a border)
            if r_end - r < 2 or c_end - c < 2:
                continue

            # Validate all four borders
            top_ok = all(grid[r][k] == color for k in range(c, c_end + 1))
            if not top_ok:
                continue

            bottom_ok = all(grid[r_end][k] == color for k in range(c, c_end + 1))
            if not bottom_ok:
                continue

            left_ok = all(grid[k][c] == color for k in range(r, r_end + 1))
            if not left_ok:
                continue

            right_ok = all(grid[k][c_end] == color for k in range(r, r_end + 1))
            if not right_ok:
                continue

            # Calculate dimensions
            height = r_end - r + 1
            width = c_end - c + 1

            # Determine fill color
            if height % 2 == 1 and width % 2 == 1:
                fill = 7
            else:
                fill = 2

            # Fill interior
            for i in range(r + 1, r_end):
                for j in range(c + 1, c_end):
                    result[i][j] = fill

    return result
